#include <stdio.h>
#include <stdlib.h>

static int readInt(int *out) {
    int c = getchar();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = getchar();
    if (c == EOF) return 0;
    int sign = 1;
    long x = 0;
    if (c == '-') { sign = -1; c = getchar(); }
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = getchar();
    }
    *out = (int)(sign * x);
    return 1;
}

int main(void) {
    int n, m;
    readInt(&n);
    readInt(&m);

    long long *col = (long long *)calloc((size_t)m, sizeof(long long));
    if (!col) return 1;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            int v;
            readInt(&v);
            col[j] += v;
        }
    }

    long long best = col[0];
    for (int j = 1; j < m; j++) {
        if (col[j] < best) best = col[j];
    }

    printf("%lld\n", best);

    free(col);
    return 0;
}
